import React, { useRef, useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    if (typeof document === "undefined") return;

    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FoodPyramidProps = Record<string, any>;

export const FoodPyramid: React.FC<FoodPyramidProps> = ({
  backgroundColor = "#f8f9fa",
  transparentBackground = false,
  durationInSeconds = 10, // Added default to match schema
  textColor = "#333333",
  tier4Label = "Minimally Processed",
  tier4SubLabel = "Vegetables, Fruits, Nuts, Fish",
  tier4Color = "#2E7D32", 
  tier4Image = "https://images.unsplash.com/photo-1615485500704-8e99099928b3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  tier3Label = "Whole Foods",
  tier3SubLabel = "Grains, Lean Protein",
  tier3Color = "#66BB6A", 
  tier3Image = "https://images.unsplash.com/photo-1506459225024-1428097a7e18?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  tier2Label = "Refined Carbs",
  tier2SubLabel = "Sweets, White Bread",
  tier2Color = "#FFA726", 
  tier2Image = "https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  tier1Label = "Ultra-Processed",
  tier1SubLabel = "Sugary Drinks, Fast Food",
  tier1Color = "#D84315", 
  tier1Image = "https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
}) => {
  useFontLoader(["Poppins"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Generate a unique ID to prevent SVG definition collisions
  const uniqueId = useMemo(() => `fp-${Math.random().toString(36).substr(2, 9)}`, []);

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Configuration for the pyramid geometry
  const pyramidHeight = height * 0.75;
  const pyramidBaseWidth = width * 0.45;
  const centerX = width * 0.35;
  const startY = (height - pyramidHeight) / 2;
  const tierHeight = pyramidHeight / 4;

  const tiers = [
    { 
      id: 4, 
      label: tier4Label, 
      sub: tier4SubLabel, 
      color: tier4Color, 
      image: tier4Image,
      visualIndex: 0 // Top
    },
    { 
      id: 3, 
      label: tier3Label, 
      sub: tier3SubLabel, 
      color: tier3Color, 
      image: tier3Image,
      visualIndex: 1 
    },
    { 
      id: 2, 
      label: tier2Label, 
      sub: tier2SubLabel, 
      color: tier2Color, 
      image: tier2Image,
      visualIndex: 2 
    },
    { 
      id: 1, 
      label: tier1Label, 
      sub: tier1SubLabel, 
      color: tier1Color, 
      image: tier1Image,
      visualIndex: 3 // Bottom
    },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Poppins",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        <defs>
          <filter id={`${uniqueId}-shadow`} x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow dx="0" dy="4" stdDeviation="6" floodColor="#000000" floodOpacity="0.15" />
          </filter>
        </defs>

        {tiers.map((tier) => {
          // Calculate Trapezoid Coordinates
          const i = tier.visualIndex;
          
          const segTopY = startY + i * tierHeight;
          const segBottomY = startY + (i + 1) * tierHeight;
          
          // Width calculations
          const halfWidthTop = (i / 4) * (pyramidBaseWidth / 2);
          const halfWidthBottom = ((i + 1) / 4) * (pyramidBaseWidth / 2);

          const tl = { x: centerX - halfWidthTop, y: segTopY };
          const tr = { x: centerX + halfWidthTop, y: segTopY };
          const br = { x: centerX + halfWidthBottom, y: segBottomY };
          const bl = { x: centerX - halfWidthBottom, y: segBottomY };

          const pathD = `M ${tl.x} ${tl.y} L ${tr.x} ${tr.y} L ${br.x} ${br.y} L ${bl.x} ${bl.y} Z`;

          // Animation Logic
          const orderIndex = 4 - tier.id; // 0 for Tier 1, 3 for Tier 4
          const delayFrames = orderIndex * 12; // 12 frames stagger
          
          const entrance = spring({
            frame: frame - delayFrames,
            fps,
            config: { damping: 14, stiffness: 120, mass: 0.8 },
          });

          // Move from bottom up
          const translateY = interpolate(entrance, [0, 1], [100, 0]);
          const opacity = interpolate(entrance, [0, 1], [0, 1]);
          const scale = interpolate(entrance, [0, 1], [0.8, 1]);

          // Layout for Text Side
          const midY = (segTopY + segBottomY) / 2;
          const midHalfWidth = (halfWidthTop + halfWidthBottom) / 2;
          const rightEdgeX = centerX + midHalfWidth;
          
          const textStartX = centerX + (pyramidBaseWidth / 2) + 60;
          const lineStartX = rightEdgeX + 10;
          const lineEndX = textStartX - 20;

          const clipId = `${uniqueId}-clip-${tier.id}`;

          return (
            <g 
              key={tier.id} 
              style={{ 
                opacity,
                transformBox: "fill-box",
                transformOrigin: "center bottom",
                transform: `translateY(${translateY}px) scale(${scale})`
              }}
            >
              <defs>
                <clipPath id={clipId}>
                  <path d={pathD} />
                </clipPath>
              </defs>

              {/* 1. Base Color Fill */}
              <path
                d={pathD}
                fill={tier.color}
                filter={`url(#${uniqueId}-shadow)`}
              />

              {/* 2. Real Food Image Masked inside Pyramid */}
              <image
                href={tier.image}
                x={centerX - pyramidBaseWidth/2}
                y={segTopY}
                width={pyramidBaseWidth}
                height={tierHeight}
                preserveAspectRatio="xMidYMid slice"
                clipPath={`url(#${clipId})`}
                style={{ opacity: 0.9 }} 
              />
              
              {/* 3. Border Stroke on top */}
              <path
                d={pathD}
                fill="none"
                stroke="white"
                strokeWidth="4"
                strokeLinejoin="round"
              />
              
              {/* 4. Connecting Line */}
              <line
                x1={lineStartX}
                y1={midY}
                x2={lineEndX}
                y2={midY}
                stroke={tier.color}
                strokeWidth="3"
                strokeLinecap="round"
                strokeDasharray="4 4"
              />

              {/* 5. Side Labels */}
              <text
                x={textStartX}
                y={midY - 10}
                textAnchor="start"
                fill={tier.color}
                style={{
                  fontSize: 32,
                  fontWeight: 700,
                  textShadow: "0px 1px 2px rgba(0,0,0,0.1)",
                }}
                dominantBaseline="middle"
              >
                {tier.label}
              </text>
              <text
                x={textStartX}
                y={midY + 20}
                textAnchor="start"
                fill={textColor}
                style={{
                  fontSize: 20,
                  fontWeight: 400,
                  opacity: 0.8,
                }}
                dominantBaseline="middle"
              >
                {tier.sub}
              </text>
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default FoodPyramid;